#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "YOUR_WIFI_NAME";
const char* password = "YOUR_WIFI_PASSWORD";

WebServer server(80);

void handleRoot() {
  String html = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>ESP32 Control Panel</title>
  <style>
    body {
      font-family: Arial;
      text-align: center;
      background: #111;
      color: white;
      padding: 30px;
    }

    .card {
      max-width: 500px;
      margin: auto;
      padding: 25px;
      border-radius: 20px;
      background: #222;
    }

    h1 {
      color: #00ff88;
    }

    .value {
      font-size: 25px;
      margin: 15px;
    }
  </style>
</head>

<body>

<div class="card">
  <h1>ESP32 is Online 🚀</h1>

  <div class="value">
    Uptime: <span id="uptime">Loading...</span>
  </div>

  <div class="value">
    Free RAM: <span id="ram">Loading...</span> bytes
  </div>

  <div class="value">
    Chip: ESP32
  </div>
</div>

<script>
function update() {
  fetch('/status')
    .then(response => response.json())
    .then(data => {
      document.getElementById('uptime').innerText =
        data.uptime + " seconds";

      document.getElementById('ram').innerText =
        data.ram;
    });
}

setInterval(update, 1000);
update();
</script>

</body>
</html>
)rawliteral";

  server.send(200, "text/html", html);
}

void handleStatus() {
  String json = "{";
  json += "\"uptime\":" + String(millis() / 1000);
  json += ",";
  json += "\"ram\":" + String(ESP.getFreeHeap());
  json += "}";

  server.send(200, "application/json", json);
}

void setup() {
  Serial.begin(115200);

  Serial.println();
  Serial.println("Connecting to WiFi...");

  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println();
  Serial.println("WiFi connected!");
  Serial.print("ESP32 IP: ");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/status", handleStatus);

  server.begin();

  Serial.println("Web server started!");
}

void loop() {
  server.handleClient();
}
